#!/usr/bin/env python3
"""Twenty-fourth pass: open the evidence. Events, the fold, the vectors, the trace.

Run from the project root:   .venv/bin/python quality_pass24.py

The project's central claim is that every answer is derived from evidence and can
name it. Until now that was only checkable from the inside: `check_grounding`
asserted it and you had to trust the assertion. Nobody could open the log, read
the chunk an answer cited, or watch the reranker change its mind.

WHAT THIS ADDS

`app/review/store.py`  - read-only views over the event log, the fold, the vector
index and the answer log. One layer with no UI in it, so the Gradio tab and the
API serve the SAME numbers from the same functions rather than two
implementations that drift apart.

A "Data & Retrieval" tab, and /review/* on the API. Six views:

  Overview     what the answers are built from, and whether the index is there
  Event log    the append-only log, filtered; every type and how often it occurs
  Fold         a repair order's events beside the state they fold into
  Vector store what is in the index, one chunk in full, and a health sample
  Retrieval    BOTH stages of a real search, with what the reranker changed
  Answers      what was asked, what it cited, whether grounding passed

THE RETRIEVAL TRACE IS THE POINT

`search_updates` returns six passages and nothing about how they were chosen. The
trace runs the same query embedding, the same wide retrieve and the same rerank,
and keeps the intermediate stage - so a passage that the vector search ranked
seventh and the reranker promoted to third is visible as exactly that. The
reranker either earns its place on screen or it does not.

It mirrors app/retrieval/index.py rather than sharing its code, because it needs
the stage that `search` throws away. scripts/test_review.py --live asserts the two
still cite the same six ids; that test is what will notice if retrieval is ever
tuned in one place and not the other.

THREE THINGS THE CHECKS CAUGHT IN THIS PASS ITSELF

  * `overview()` reported a row of zeros for a database that did not exist. A
    missing schema and an empty shop produce the same COUNT. It says which now.

  * The chunk browser pulled every 1024-float vector into Python and then threw
    them away - about 8 KB of object churn per row to read a text field. Arrow
    drops the column before any of it becomes Python, and `index_health()` samples
    the vectors deliberately, because a zero norm is a failed embedding and
    nothing else in the module would ever have looked.

  * The snapshot was tested for JSON with `json.dumps(v, default=str)`, which
    serialises almost anything - so the guard passed and raw `OpStatus` dataclasses
    went into the payload for the JSON viewer and FastAPI to choke on. Testing with
    a converter that always succeeds is not a test.

ONE WRITE

`log_answer` records what each answer cited, so "100% of findings linked to
evidence" can be read from the other end: for any chunk, which answers used it.
It is on the hot path of every question, so it swallows every exception and can
be turned off with ASOIA_LOG_ANSWERS=0. An audit trail that can break answering
is worse than no audit trail.
"""
import sys, pathlib, ast

ROOT = pathlib.Path(".")
CHANGES = []


def edit(rel, old, new, label, skip_if=None):
    p = ROOT / rel
    if not p.exists():
        sys.exit(f"FAIL: {rel} not found - run from the project root")
    s = p.read_text()
    if skip_if and skip_if in s:
        CHANGES.append(f"  skip  {label} (already applied)")
        return
    n = s.count(old)
    if n != 1:
        sys.exit(f"FAIL: {label}: anchor found {n} times in {rel}, expected 1.\n"
                 "      Run passes 1-23 first. Stopping without changes.")
    p.write_text(s.replace(old, new, 1))
    CHANGES.append(f"  ok    {label}")


def write(rel, body, label):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    if p.exists():
        if p.read_text() == body:
            CHANGES.append(f"  skip  {label} (already present)")
        else:
            p.write_text(body)
            CHANGES.append(f"  ok    {label} (replaced)")
        return
    p.write_text(body)
    CHANGES.append(f"  ok    {label}")


# ==================== 1. the read-only layer
write('app/review/__init__.py',
      '"""Read-only review of everything the agent stands on.\n\nSeparate from app/analytics because that answers questions and this one shows\nthe evidence: no derived insight, no scoring, and no writes except the\nbest-effort answer log. See store.py.\n"""\n',
      'app/review/__init__.py  the package')

write('app/review/store.py',
      '"""Read-only views over everything the agent stands on: events, updates, vectors.\n\nWHY THIS EXISTS\n\nThe project\'s central claim is that every answer is derived from evidence and can\nname it. Until now that claim was only checkable from the inside - `check_grounding`\nasserted it, and you had to trust the assertion. Nobody could open the log, read the\nchunk an answer cited, or watch the reranker change its mind.\n\nThis module is the evidence, exposed. It is deliberately one layer with no UI in it,\nso `app/ui/gradio_app.py` and `app/api/server.py` show the SAME numbers rather than\ntwo implementations that drift, and so the tests can call it directly.\n\nThree rules it keeps:\n\n  * READ ONLY. Nothing here writes. The one write in the system\'s review path is\n    `log_answer`, which is separate, best-effort, and can be turned off.\n  * NO VECTORS IN LIST VIEWS. A 1024-float vector per row turns a table browse into\n    megabytes. Lists carry the dimension and the norm; the single-chunk view carries\n    a preview.\n  * A CONNECTION PER CALL. Gradio and FastAPI both run handlers on worker threads,\n    and a SQLite connection belongs to the thread that made it. Passing one around\n    is the bug pass 19 had to fix.\n"""\nfrom __future__ import annotations\nimport json\nimport math\nimport os\nimport sqlite3\nimport time\nfrom dataclasses import fields as dc_fields, is_dataclass\nfrom datetime import date, datetime, timedelta\nfrom enum import Enum\nfrom typing import Any\n\nfrom app.state import db as dbm\n\n# Mirrors app/retrieval/index.py. Imported lazily everywhere so that the event and\n# update views keep working on a box where lancedb is not installed.\nLANCE_URI = os.environ.get("LANCE_URI", "data/generated/lancedb")\nTABLE = "updates"\n\n# What search_updates() actually uses. The trace has to match it or it is a\n# demonstration of something else; test_review.py asserts they agree.\nRETRIEVE_N = 18\nRERANK_N = 6\n\n\ndef _con(con: sqlite3.Connection | None = None) -> sqlite3.Connection:\n    return con if con is not None else dbm.connect()\n\n\ndef _rows(cur) -> list[dict]:\n    return [dict(r) for r in cur]\n\n\n# ---------------------------------------------------------------- the event log\n\ndef events(ro_number: str | None = None, actor_id: str | None = None,\n           event_type: str | None = None, since_hours: int | None = None,\n           text: str | None = None, limit: int = 200, offset: int = 0,\n           con: sqlite3.Connection | None = None) -> dict:\n    """The append-only log, filtered. Newest first, because that is what is asked for."""\n    c = _con(con)\n    where, args = [], []\n    if ro_number:\n        where.append("ro_number = ?"); args.append(ro_number)\n    if actor_id:\n        where.append("actor_id = ?"); args.append(actor_id)\n    if event_type:\n        where.append("type = ?"); args.append(event_type)\n    if since_hours:\n        cutoff = (datetime.now() - timedelta(hours=since_hours)).isoformat()\n        where.append("at >= ?"); args.append(cutoff)\n    if text:\n        where.append("payload LIKE ?"); args.append(f"%{text}%")\n    clause = (" WHERE " + " AND ".join(where)) if where else ""\n\n    total = c.execute(f"SELECT COUNT(*) FROM events{clause}", args).fetchone()[0]\n    rows = _rows(c.execute(\n        f"SELECT event_id, ro_number, type, at, actor_id, shift, source_update_id, "\n        f"payload FROM events{clause} ORDER BY at DESC, event_id DESC LIMIT ? OFFSET ?",\n        (*args, limit, offset)))\n    for r in rows:\n        try:\n            r["payload"] = json.loads(r["payload"])\n        except (TypeError, ValueError):\n            pass\n    return {"total": total, "returned": len(rows), "offset": offset, "events": rows}\n\n\ndef event_types(con: sqlite3.Connection | None = None) -> list[dict]:\n    """Every event type with its count. Seventeen are defined; this shows which are used."""\n    c = _con(con)\n    return _rows(c.execute(\n        "SELECT type, COUNT(*) AS n, MIN(at) AS first_at, MAX(at) AS last_at "\n        "FROM events GROUP BY type ORDER BY n DESC"))\n\n\ndef actors(con: sqlite3.Connection | None = None) -> list[dict]:\n    c = _con(con)\n    return _rows(c.execute(\n        "SELECT e.actor_id, COALESCE(s.name, e.actor_id) AS name, COUNT(*) AS n "\n        "FROM events e LEFT JOIN staff s ON s.staff_id = e.actor_id "\n        "GROUP BY e.actor_id ORDER BY n DESC"))\n\n\n# ------------------------------------------------------- the fold, and its inputs\n\ndef ro_review(ro_number: str, con: sqlite3.Connection | None = None) -> dict:\n    """A repair order\'s derived state NEXT TO the events it was derived from.\n\n    The point of the side-by-side: state is not stored anywhere, it is folded from\n    the log on every read. Showing the fold beside its inputs is the difference\n    between asserting that and demonstrating it.\n    """\n    c = _con(con)\n    ro = dbm.get_ro(c, ro_number)\n    if not ro:\n        return {"error": f"no repair order {ro_number}"}\n    evs = dbm.events_for_ro(c, ro_number)\n\n    snap = None\n    try:\n        from app.state.engine import fold\n        promised = ro.get("promised_time")\n        snap = fold(evs, promised_time=datetime.fromisoformat(promised) if promised else None)\n    except Exception as e:                       # a fold bug must not blank the page\n        return {"ro": ro, "fold_error": f"{type(e).__name__}: {e}",\n                "events": [e_.as_dict() for e_ in evs]}\n\n    state = getattr(snap, "state", None)\n    return {\n        "ro": ro,\n        "event_count": len(evs),\n        "state": getattr(state, "value", str(state)),\n        "snapshot": _snapshot_dict(snap),\n        "events": [e_.as_dict() for e_ in evs],\n        "updates": _rows(c.execute(\n            "SELECT update_id, staff_id, at, shift, text FROM updates "\n            "WHERE ro_number = ? ORDER BY at", (ro_number,))),\n    }\n\n\ndef _jsonable(v: Any, depth: int = 0) -> Any:\n    """Anything a snapshot holds, as real JSON.\n\n    A snapshot carries nested dataclasses (`OpStatus`), enums and datetimes. The\n    first version of this tested them with `json.dumps(v, default=str)`, which\n    serialises almost anything - so the guard passed and the raw object went into\n    the payload, where the JSON viewer and FastAPI would both choke on it. Testing\n    with a converter that always succeeds is not a test. This converts instead.\n    """\n    if depth > 6:\n        return str(v)\n    if v is None or isinstance(v, (bool, int, float, str)):\n        return v\n    if isinstance(v, Enum):\n        return v.value\n    if isinstance(v, (datetime, date)):\n        return v.isoformat()\n    if isinstance(v, timedelta):\n        return v.total_seconds()\n    if is_dataclass(v) and not isinstance(v, type):\n        return {f.name: _jsonable(getattr(v, f.name, None), depth + 1)\n                for f in dc_fields(v)}\n    if isinstance(v, dict):\n        return {str(k): _jsonable(x, depth + 1) for k, x in v.items()}\n    if isinstance(v, (list, tuple, set, frozenset)):\n        return [_jsonable(x, depth + 1) for x in v]\n    try:\n        json.dumps(v)\n        return v\n    except (TypeError, ValueError):\n        return str(v)\n\n\ndef _snapshot_dict(snap) -> dict:\n    """A snapshot as plain JSON, whatever fields it happens to carry."""\n    out: dict[str, Any] = {}\n    for k in dir(snap):\n        if k.startswith("_"):\n            continue\n        v = getattr(snap, k, None)\n        if callable(v):\n            continue\n        out[k] = _jsonable(v)\n    return out\n\n\ndef updates(ro_number: str | None = None, staff_id: str | None = None,\n            text: str | None = None, limit: int = 200, offset: int = 0,\n            con: sqlite3.Connection | None = None) -> dict:\n    """The technician updates as written - the raw material the vectors are built from."""\n    c = _con(con)\n    where, args = [], []\n    if ro_number:\n        where.append("u.ro_number = ?"); args.append(ro_number)\n    if staff_id:\n        where.append("u.staff_id = ?"); args.append(staff_id)\n    if text:\n        where.append("u.text LIKE ?"); args.append(f"%{text}%")\n    clause = (" WHERE " + " AND ".join(where)) if where else ""\n    total = c.execute(f"SELECT COUNT(*) FROM updates u{clause}", args).fetchone()[0]\n    rows = _rows(c.execute(\n        f"SELECT u.update_id, u.ro_number, u.staff_id, COALESCE(s.name, u.staff_id) "\n        f"AS staff_name, u.at, u.shift, u.text FROM updates u "\n        f"LEFT JOIN staff s ON s.staff_id = u.staff_id{clause} "\n        f"ORDER BY u.at DESC LIMIT ? OFFSET ?", (*args, limit, offset)))\n    return {"total": total, "returned": len(rows), "offset": offset, "updates": rows}\n\n\n# ------------------------------------------------------------- the vector store\n\nNO_LANCEDB = ("lancedb is not installed - the vector views need it. "\n              "uv pip install --python .venv lancedb")\n\n\ndef _table(uri: str | None = None):\n    try:\n        import lancedb\n    except ImportError:\n        raise RuntimeError(NO_LANCEDB) from None\n    db = lancedb.connect(uri or LANCE_URI)\n    if TABLE not in db.table_names():\n        raise RuntimeError(\n            f"no \'{TABLE}\' table at {uri or LANCE_URI} - build the index first: "\n            f".venv/bin/python -c \'from app.retrieval.index import build; print(build())\'")\n    return db.open_table(TABLE)\n\n\ndef _scan(tbl, drop_vector: bool = True) -> list[dict]:\n    """Every row, as dicts. Drops the vector COLUMN rather than the values.\n\n    `to_list()` builds a Python list of 1024 floats for every row and then the\n    caller throws them away - about 8 KB of object churn per row to read a text\n    field. Arrow drops the column before any of it becomes Python.\n    """\n    try:\n        t = tbl.to_arrow()\n        if drop_vector and "vector" in t.column_names:\n            t = (t.drop_columns(["vector"]) if hasattr(t, "drop_columns")\n                 else t.drop(["vector"]))\n        return t.to_pylist()\n    except Exception:\n        rows = tbl.search().limit(100_000).to_list()\n        if drop_vector:\n            for r in rows:\n                r.pop("vector", None)\n        return rows\n\n\ndef index_health(sample: int = 64, uri: str | None = None) -> dict:\n    """Sample vectors and check they are real. A zero norm is a failed embedding.\n\n    Deliberately a sampled, separate call: the browse views never touch vectors, so\n    nothing else in this module would ever notice an index full of zeros.\n    """\n    try:\n        tbl = _table(uri)\n        recs = tbl.search().limit(sample).to_list()\n    except Exception as e:\n        return {"error": str(e)}\n    norms = []\n    for r in recs:\n        v = r.get("vector")\n        if v is None:\n            continue\n        norms.append(math.sqrt(sum(float(x) * float(x) for x in v)))\n    if not norms:\n        return {"sampled": 0, "error": "no vectors in the sample"}\n    zero = sum(1 for n in norms if n < 1e-9)\n    return {"sampled": len(norms), "zero_norm": zero,\n            "min_norm": round(min(norms), 6), "max_norm": round(max(norms), 6),\n            "mean_norm": round(sum(norms) / len(norms), 6),\n            "ok": zero == 0}\n\n\ndef index_stats(uri: str | None = None) -> dict:\n    """Is there an index, how big, how wide, and how old."""\n    uri = uri or LANCE_URI\n    out: dict[str, Any] = {"uri": uri, "table": TABLE, "exists": False}\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        out["error"] = str(e)\n        return out\n    out["exists"] = True\n    try:\n        out["rows"] = tbl.count_rows()\n    except Exception:\n        out["rows"] = None\n    try:\n        names = [f.name for f in tbl.schema]\n        out["columns"] = names\n        for f in tbl.schema:\n            if f.name == "vector":\n                out["dim"] = getattr(f.type, "list_size", None) or \\\n                             getattr(getattr(f.type, "value_type", None), "bit_width", None)\n    except Exception:\n        pass\n    if not out.get("dim"):                        # ask a row, if the schema would not say\n        try:\n            one = tbl.search().limit(1).to_list()\n            if one and one[0].get("vector") is not None:\n                out["dim"] = len(one[0]["vector"])\n        except Exception:\n            pass\n    try:\n        p = os.path.join(uri, f"{TABLE}.lance")\n        if os.path.exists(p):\n            out["built_at"] = datetime.fromtimestamp(os.path.getmtime(p)).isoformat(\n                timespec="seconds")\n            out["bytes"] = sum(\n                os.path.getsize(os.path.join(dp, f))\n                for dp, _, fs in os.walk(p) for f in fs)\n    except Exception:\n        pass\n    return out\n\n\ndef chunks(ro_number: str | None = None, text: str | None = None,\n           limit: int = 100, offset: int = 0, uri: str | None = None) -> dict:\n    """Browse what is IN the vector store, without pulling the vectors themselves.\n\n    A 1024-float vector per row is about 8 KB; a hundred of them is most of a\n    megabyte of numbers nobody reads, so the vector column is dropped in Arrow\n    before any of it becomes Python. `index_health()` samples the vectors\n    themselves, and `chunk()` shows one in full.\n    """\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {"error": str(e), "rows": [], "total": 0}\n    try:\n        recs = _scan(tbl)\n    except Exception as e:\n        return {"error": f"{type(e).__name__}: {e}", "rows": [], "total": 0}\n\n    out = []\n    for r in recs:\n        if ro_number and r.get("ro_number") != ro_number:\n            continue\n        if text and text.lower() not in (r.get("text") or "").lower():\n            continue\n        r.pop("vector", None)\n        r.pop("_distance", None)\n        out.append(r)\n    out.sort(key=lambda r: r.get("at") or "", reverse=True)\n    return {"total": len(out), "returned": min(limit, max(0, len(out) - offset)),\n            "offset": offset, "rows": out[offset:offset + limit]}\n\n\ndef chunk(update_id: str, preview_dims: int = 12, uri: str | None = None) -> dict:\n    """One chunk in full: its text, its metadata, and the front of its vector."""\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {"error": str(e)}\n    try:\n        safe = update_id.replace("\'", "\'\'")\n        try:\n            recs = tbl.search().where(f"update_id = \'{safe}\'").limit(1).to_list()\n        except Exception:      # older lancedb: no filter on an empty search\n            recs = [r for r in tbl.search().limit(100_000).to_list()\n                    if r.get("update_id") == update_id]\n    except Exception as e:\n        return {"error": f"{type(e).__name__}: {e}"}\n    if not recs:\n        return {"error": f"no chunk for update {update_id}"}\n    r = dict(recs[0])\n    v = r.pop("vector", None)\n    r.pop("_distance", None)\n    if v is not None:\n        v = [float(x) for x in v]\n        r["dim"] = len(v)\n        r["norm"] = round(math.sqrt(sum(x * x for x in v)), 6)\n        r["vector_preview"] = [round(x, 5) for x in v[:preview_dims]]\n    return r\n\n\n# ------------------------------------------------------- what retrieval actually did\n\ndef retrieval_trace(query: str, retrieve_n: int = RETRIEVE_N,\n                    rerank_n: int = RERANK_N, ro_number: str | None = None,\n                    uri: str | None = None) -> dict:\n    """Both stages of a real search, so the reranker\'s contribution is visible.\n\n    `search_updates` returns six passages and nothing about how they were chosen.\n    This runs the same two calls - the same query embedding, the same wide retrieve,\n    the same rerank - and keeps the intermediate stage, with each passage\'s movement\n    between the two.\n\n    It mirrors app/retrieval/index.py rather than sharing its code, so that it can\n    keep the stage that `search` throws away. test_review.py asserts the two agree\n    on the final citations; if they ever diverge, that test is what says so.\n    """\n    from app.nim.client import embed_query as nim_embed_query, rerank as nim_rerank\n    out: dict[str, Any] = {"query": query, "retrieve_n": retrieve_n,\n                           "rerank_n": rerank_n, "ro_number": ro_number}\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {**out, "error": str(e)}\n\n    t0 = time.perf_counter()\n    try:\n        qv = nim_embed_query(query)\n    except Exception as e:\n        return {**out, "error": f"embedding failed - {type(e).__name__}: {e}"}\n    out["embed_ms"] = round((time.perf_counter() - t0) * 1000, 1)\n    out["query_dim"] = len(qv)\n\n    t1 = time.perf_counter()\n    try:\n        q = tbl.search(qv).limit(retrieve_n)\n        if ro_number:\n            q = q.where(f"ro_number = \'{ro_number}\'")\n        hits = q.to_list()\n    except Exception as e:\n        return {**out, "error": f"vector search failed - {type(e).__name__}: {e}"}\n    out["search_ms"] = round((time.perf_counter() - t1) * 1000, 1)\n\n    retrieved = []\n    for i, h in enumerate(hits):\n        h.pop("vector", None)\n        retrieved.append({\n            "rank": i + 1, "update_id": h.get("update_id"),\n            "ro_number": h.get("ro_number"), "at": h.get("at"),\n            "by": h.get("staff_name") or h.get("staff_id"),\n            "vehicle": h.get("vehicle"), "text": h.get("text"),\n            "vector_score": h.pop("_distance", None)})\n    out["retrieved"] = retrieved\n\n    if not retrieved or rerank_n <= 0:\n        out["reranked"] = []\n        return out\n\n    t2 = time.perf_counter()\n    try:\n        ranked = nim_rerank(query, [r["text"] for r in retrieved], top_n=rerank_n)\n    except Exception as e:\n        out["rerank_error"] = f"{type(e).__name__}: {e}"\n        out["reranked"] = retrieved[:rerank_n]\n        return out\n    out["rerank_ms"] = round((time.perf_counter() - t2) * 1000, 1)\n\n    reranked = []\n    for new_rank, r in enumerate(ranked, 1):\n        src = dict(retrieved[r["index"]])\n        src["rerank_score"] = r["score"]\n        src["vector_rank"] = src.pop("rank")\n        src["rank"] = new_rank\n        src["moved"] = src["vector_rank"] - new_rank      # positive = promoted\n        reranked.append(src)\n    out["reranked"] = reranked\n\n    kept = {r["update_id"] for r in reranked}\n    out["promoted"] = [r for r in reranked if r["moved"] > 0]\n    out["dropped"] = [r for r in retrieved[:rerank_n] if r["update_id"] not in kept]\n    out["citations"] = [r["update_id"] for r in reranked]\n    return out\n\n\n# ------------------------------------------------------------ the answer log\n\nLOG_ANSWERS = os.environ.get("ASOIA_LOG_ANSWERS", "1") != "0"\n\n_ANSWER_LOG_DDL = """\nCREATE TABLE IF NOT EXISTS answer_log (\n  answer_id INTEGER PRIMARY KEY AUTOINCREMENT,\n  at TEXT NOT NULL, question TEXT NOT NULL, answer TEXT,\n  route TEXT, composed TEXT, grounded INTEGER,\n  tools TEXT, citations TEXT, warnings TEXT, seconds REAL\n);\nCREATE INDEX IF NOT EXISTS idx_answer_log_at ON answer_log(at);\n"""\n\n\ndef ensure_answer_log(con: sqlite3.Connection | None = None) -> None:\n    c = _con(con)\n    c.executescript(_ANSWER_LOG_DDL)\n    c.commit()\n\n\ndef log_answer(ans, seconds: float | None = None) -> None:\n    """Record that an answer was given, and what it cited. Best effort, always.\n\n    This is the only write in the review path, and it is on the hot path of every\n    question, so it cannot fail loudly and it cannot be slow. Every exception is\n    swallowed: an audit trail that can break answering is worse than no audit trail.\n    Set ASOIA_LOG_ANSWERS=0 to turn it off.\n    """\n    if not LOG_ANSWERS:\n        return\n    try:\n        c = dbm.connect()\n        ensure_answer_log(c)\n        c.execute(\n            "INSERT INTO answer_log (at, question, answer, route, composed, grounded, "\n            "tools, citations, warnings, seconds) VALUES (?,?,?,?,?,?,?,?,?,?)",\n            (datetime.now().isoformat(timespec="seconds"),\n             ans.question, ans.text, ans.route, ans.composed, int(bool(ans.grounded)),\n             json.dumps([t.get("name") for t in (ans.tool_calls or [])]),\n             json.dumps(ans.citations or []),\n             json.dumps(ans.warnings or []),\n             round(seconds, 3) if seconds is not None else None))\n        c.commit()\n    except Exception:\n        pass\n\n\ndef answers(limit: int = 100, offset: int = 0, grounded: bool | None = None,\n            con: sqlite3.Connection | None = None) -> dict:\n    """What has been asked, what it cited, and whether it was grounded."""\n    c = _con(con)\n    try:\n        ensure_answer_log(c)\n    except Exception as e:\n        return {"error": str(e), "total": 0, "answers": []}\n    where, args = [], []\n    if grounded is not None:\n        where.append("grounded = ?"); args.append(int(grounded))\n    clause = (" WHERE " + " AND ".join(where)) if where else ""\n    total = c.execute(f"SELECT COUNT(*) FROM answer_log{clause}", args).fetchone()[0]\n    rows = _rows(c.execute(\n        f"SELECT * FROM answer_log{clause} ORDER BY answer_id DESC LIMIT ? OFFSET ?",\n        (*args, limit, offset)))\n    for r in rows:\n        for k in ("tools", "citations", "warnings"):\n            try:\n                r[k] = json.loads(r[k]) if r[k] else []\n            except (TypeError, ValueError):\n                r[k] = []\n        r["grounded"] = bool(r["grounded"])\n    return {"total": total, "returned": len(rows), "offset": offset, "answers": rows}\n\n\ndef cited_by(update_id: str, con: sqlite3.Connection | None = None) -> dict:\n    """Which answers cited this update. The traceability claim, from the other end."""\n    c = _con(con)\n    try:\n        ensure_answer_log(c)\n    except Exception as e:\n        return {"error": str(e), "answers": []}\n    rows = _rows(c.execute(\n        "SELECT answer_id, at, question, route, grounded, citations FROM answer_log "\n        "WHERE citations LIKE ? ORDER BY answer_id DESC LIMIT 100", (f\'%"{update_id}"%\',)))\n    for r in rows:\n        try:\n            r["citations"] = json.loads(r["citations"])\n        except (TypeError, ValueError):\n            r["citations"] = []\n        r["grounded"] = bool(r["grounded"])\n    # LIKE can match a longer id that contains this one; confirm exactly.\n    rows = [r for r in rows if update_id in r["citations"]]\n    return {"update_id": update_id, "count": len(rows), "answers": rows}\n\n\ndef overview(con: sqlite3.Connection | None = None) -> dict:\n    """One call for the top of the review screen."""\n    c = _con(con)\n    # A missing schema and an empty shop both return nothing from every COUNT. The\n    # first draft of this reported a row of zeros for a database that did not exist,\n    # which is the kind of confident wrong answer the ASR check was full of.\n    try:\n        have = {r[0] for r in c.execute(\n            "SELECT name FROM sqlite_master WHERE type=\'table\'")}\n    except Exception as e:\n        return {"database": f"unreadable - {type(e).__name__}: {e}"}\n    missing = {"ros", "events", "updates", "staff"} - have\n    if missing:\n        return {"database": f"no schema - missing {\', \'.join(sorted(missing))}. "\n                            f"Generate the dataset first (notebook 01, or "\n                            f"scripts/verify_data.py to check one that exists).",\n                "tables": sorted(have)}\n\n    def n(sql):\n        try:\n            return c.execute(sql).fetchone()[0]\n        except Exception:\n            return None\n    idx = index_stats()\n    logged = 0\n    try:\n        ensure_answer_log(c)\n        logged = c.execute("SELECT COUNT(*) FROM answer_log").fetchone()[0]\n    except Exception:\n        pass\n    return {\n        "database": "ok",\n        "repair_orders": n("SELECT COUNT(*) FROM ros"),\n        "events": n("SELECT COUNT(*) FROM events"),\n        "event_types_used": n("SELECT COUNT(DISTINCT type) FROM events"),\n        "updates": n("SELECT COUNT(*) FROM updates"),\n        "staff": n("SELECT COUNT(*) FROM staff"),\n        "first_event": n("SELECT MIN(at) FROM events"),\n        "last_event": n("SELECT MAX(at) FROM events"),\n        "vector_rows": idx.get("rows"),\n        "vector_dim": idx.get("dim"),\n        "vector_uri": idx.get("uri"),\n        "vector_error": idx.get("error"),\n        "answers_logged": logged,\n    }\n',
      'app/review/store.py  events, the fold, the vectors, the trace')


# ==================== 2. the Gradio tab
edit('app/ui/gradio_app.py',
     'def build() -> gr.Blocks:',
     '# ----------------------------------------------------------------- review views\nfrom app.state.events import EventType as _EventType\n\n_EVENT_TYPES = list(_EventType)\n\n# Every one of these calls app/review/store.py and formats what comes back. No\n# query lives here: the API serves the same numbers from the same functions, and\n# two implementations of "how many events are there" would eventually disagree.\n\ndef _df(rows: list[dict], cols: list[str], trunc: dict | None = None) -> pd.DataFrame:\n    """Selected columns, in order, with long text cut to keep a row one line high."""\n    trunc = trunc or {}\n    if not rows:\n        return pd.DataFrame(columns=cols)\n    out = []\n    for r in rows:\n        d = {}\n        for c in cols:\n            v = r.get(c)\n            if isinstance(v, (dict, list)):\n                v = json.dumps(v, default=str)\n            if c in trunc and isinstance(v, str) and len(v) > trunc[c]:\n                v = v[:trunc[c]] + "…"\n            d[c] = v\n        out.append(d)\n    return pd.DataFrame(out, columns=cols)\n\n\ndef ui_review_overview():\n    from app.review import store as RS\n    o = RS.overview()\n    if o.get("database") != "ok":\n        return f"### No data\\n\\n{o.get(\'database\')}"\n    vec = (f"{o[\'vector_rows\']} chunks, {o[\'vector_dim\']} dimensions"\n           if o.get("vector_rows") else f"**not available** — {o.get(\'vector_error\')}")\n    return (\n        "### What the answers are built from\\n\\n"\n        f"| | |\\n|---|---|\\n"\n        f"| Repair orders | {o[\'repair_orders\']} |\\n"\n        f"| Events | {o[\'events\']} across {o[\'event_types_used\']} of 17 types |\\n"\n        f"| Technician updates | {o[\'updates\']} |\\n"\n        f"| Staff | {o[\'staff\']} |\\n"\n        f"| Window | {str(o[\'first_event\'])[:16]} → {str(o[\'last_event\'])[:16]} |\\n"\n        f"| Vector index | {vec} |\\n"\n        f"| Answers logged | {o[\'answers_logged\']} |\\n\\n"\n        "State is **not stored**. Every repair order\'s state is folded from its "\n        "events on each read — the Fold tab shows that happening.")\n\n\ndef ui_review_events(ro, etype, actor, hours, limit):\n    from app.review import store as RS\n    r = RS.events(ro_number=ro or None, event_type=(etype or None) if etype != "all" else None,\n                  actor_id=actor or None, since_hours=int(hours) if hours else None,\n                  limit=int(limit))\n    df = _df(r["events"], ["at", "type", "ro_number", "actor_id", "shift",\n                           "source_update_id", "payload", "event_id"],\n             {"payload": 110})\n    return f"{r[\'returned\']} of {r[\'total\']} matching events", df\n\n\ndef ui_review_event_types():\n    from app.review import store as RS\n    return _df(RS.event_types(), ["type", "n", "first_at", "last_at"])\n\n\ndef ui_review_fold(ro_number):\n    from app.review import store as RS\n    if not ro_number:\n        return "Pick a repair order.", pd.DataFrame(), pd.DataFrame(), {}\n    r = RS.ro_review(ro_number)\n    if r.get("error"):\n        return f"**{r[\'error\']}**", pd.DataFrame(), pd.DataFrame(), {}\n    if r.get("fold_error"):\n        return (f"**The fold failed:** {r[\'fold_error\']}", pd.DataFrame(),\n                pd.DataFrame(), {})\n    ro = r["ro"]\n    md = (f"### {ro_number} — {r[\'state\']}\\n\\n"\n          f"{ro.get(\'model_year\',\'\')} {ro.get(\'make\',\'\')} {ro.get(\'model\',\'\')} · "\n          f"{ro.get(\'category\',\'\')}\\n\\n"\n          f"**Concern:** {ro.get(\'concern\',\'\')}\\n\\n"\n          f"{r[\'event_count\']} events folded into the state on the right. "\n          f"Nothing below was read from a state column — there isn\'t one.")\n    evs = _df(r["events"], ["at", "type", "actor_id", "shift",\n                            "source_update_id", "payload"], {"payload": 90})\n    ups = _df(r["updates"], ["at", "update_id", "staff_id", "shift", "text"],\n              {"text": 160})\n    return md, evs, ups, r["snapshot"]\n\n\ndef ui_review_index():\n    from app.review import store as RS\n    s = RS.index_stats()\n    if not s.get("exists"):\n        return (f"### No vector index\\n\\n{s.get(\'error\')}\\n\\n"\n                "Build it with:\\n\\n"\n                "```\\n.venv/bin/python -c \'from app.retrieval.index import build; "\n                "print(build())\'\\n```")\n    h = RS.index_health()\n    size = f"{s[\'bytes\'] / 1e6:.1f} MB" if s.get("bytes") else "—"\n    health = (f"{h[\'sampled\']} sampled, {h[\'zero_norm\']} with a zero norm, "\n              f"norms {h.get(\'min_norm\')}–{h.get(\'max_norm\')}"\n              if "sampled" in h else h.get("error", "—"))\n    warn = ("" if h.get("ok", True) else\n            "\\n\\n**Some vectors are zero.** Those chunks can never be retrieved; "\n            "rebuild the index.")\n    return (f"### Vector index\\n\\n"\n            f"| | |\\n|---|---|\\n"\n            f"| Location | `{s[\'uri\']}` / `{s[\'table\']}` |\\n"\n            f"| Chunks | {s.get(\'rows\')} |\\n"\n            f"| Dimensions | {s.get(\'dim\')} |\\n"\n            f"| Built | {s.get(\'built_at\', \'—\')} |\\n"\n            f"| Size | {size} |\\n"\n            f"| Health | {health} |{warn}")\n\n\ndef ui_review_chunks(ro, text, limit):\n    from app.review import store as RS\n    r = RS.chunks(ro_number=ro or None, text=text or None, limit=int(limit))\n    if r.get("error"):\n        return f"**{r[\'error\']}**", pd.DataFrame()\n    return (f"{r[\'returned\']} of {r[\'total\']} chunks",\n            _df(r["rows"], ["update_id", "ro_number", "at", "staff_name",\n                            "vehicle", "category", "text"], {"text": 150}))\n\n\ndef ui_review_chunk(update_id):\n    from app.review import store as RS\n    if not update_id:\n        return "Paste an update id from the table above.", {}\n    c = RS.chunk(update_id.strip())\n    if c.get("error"):\n        return f"**{c[\'error\']}**", {}\n    cb = RS.cited_by(update_id.strip())\n    lines = [f"### {c.get(\'update_id\')}",\n             f"**{c.get(\'ro_number\')}** · {c.get(\'at\')} · "\n             f"{c.get(\'staff_name\') or c.get(\'staff_id\')} · {c.get(\'vehicle\',\'\')}",\n             "", "> " + (c.get("text") or ""), "",\n             f"Vector: {c.get(\'dim\')} dimensions, norm {c.get(\'norm\')}",\n             f"First values: `{c.get(\'vector_preview\')}`", ""]\n    if cb.get("count"):\n        lines.append(f"**Cited by {cb[\'count\']} answer(s):**")\n        lines += [f"- #{a[\'answer_id\']} {a[\'at\']} — {a[\'question\']}"\n                  for a in cb["answers"][:10]]\n    else:\n        lines.append("_No logged answer has cited this chunk yet._")\n    return "\\n".join(lines), c\n\n\ndef ui_review_trace(query, retrieve_n, rerank_n, ro):\n    from app.review import store as RS\n    if not (query or "").strip():\n        return ("Type a question. It runs the real embedding, the real vector "\n                "search and the real reranker.", pd.DataFrame(), pd.DataFrame())\n    t = RS.retrieval_trace(query, retrieve_n=int(retrieve_n), rerank_n=int(rerank_n),\n                           ro_number=ro or None)\n    if t.get("error"):\n        return f"**{t[\'error\']}**", pd.DataFrame(), pd.DataFrame()\n    got = _df(t["retrieved"], ["rank", "vector_score", "update_id", "ro_number",\n                               "at", "by", "text"], {"text": 130})\n    rr = _df(t["reranked"], ["rank", "vector_rank", "moved", "rerank_score",\n                             "update_id", "ro_number", "by", "text"], {"text": 130})\n    if t.get("rerank_error"):\n        head = (f"**The reranker failed:** {t[\'rerank_error\']}. The right-hand "\n                f"table is the vector order, untouched.")\n    else:\n        moved = [f"#{r[\'vector_rank\']}→#{r[\'rank\']}" for r in t["reranked"]\n                 if r["moved"] != 0]\n        dropped = [r["update_id"] for r in t["dropped"]]\n        head = (f"Embedded in {t.get(\'embed_ms\')} ms ({t.get(\'query_dim\')} dims), "\n                f"searched in {t.get(\'search_ms\')} ms, reranked in "\n                f"{t.get(\'rerank_ms\')} ms.\\n\\n"\n                f"**The reranker moved {len(moved)} of {len(t[\'reranked\'])}**"\n                + (f": {\', \'.join(moved)}. " if moved else ". ")\n                + (f"It dropped {\', \'.join(dropped)}, which the vector search had "\n                   f"in its top {len(t[\'reranked\'])}."\n                   if dropped else "It kept the vector order\'s top results.")\n                + "\\n\\nThese six ids are exactly what `search_updates` would cite.")\n    return head, got, rr\n\n\ndef ui_review_answers(which, limit):\n    from app.review import store as RS\n    g = {"all": None, "grounded": True, "ungrounded": False}[which]\n    r = RS.answers(limit=int(limit), grounded=g)\n    if r.get("error"):\n        return f"**{r[\'error\']}**", pd.DataFrame()\n    return (f"{r[\'returned\']} of {r[\'total\']} logged answers",\n            _df(r["answers"], ["answer_id", "at", "route", "composed", "grounded",\n                               "seconds", "tools", "citations", "warnings",\n                               "question", "answer"],\n                {"question": 90, "answer": 140}))\n\ndef build() -> gr.Blocks:',
     'gradio_app.py  the review handlers',
     skip_if='def ui_review_overview')

