import importlib, json, sqlite3, tempfile, os
from app.review import store as RS
importlib.reload(RS)
bad = 0

# ---- the JSON converter, which the first draft got wrong
from dataclasses import dataclass
from datetime import datetime as _dt
from enum import Enum as _Enum


class _S(_Enum):
    OPEN = "OPEN"


@dataclass
class _Op:
    code: str
    state: _S
    at: _dt


print("\nthe snapshot converter:")
cases = [
    ("an enum becomes its value", RS._jsonable(_S.OPEN), "OPEN"),
    ("a datetime becomes ISO", RS._jsonable(_dt(2026, 9, 26, 12, 0)),
     "2026-09-26T12:00:00"),
    ("a nested dataclass becomes a dict",
     RS._jsonable(_Op("BRK-01", _S.OPEN, _dt(2026, 9, 26))),
     {"code": "BRK-01", "state": "OPEN", "at": "2026-09-26T00:00:00"}),
    ("a list of dataclasses converts",
     RS._jsonable([_Op("A", _S.OPEN, _dt(2026, 9, 26))])[0]["code"], "A"),
    ("a set becomes a list", sorted(RS._jsonable({"b", "a"})), ["a", "b"]),
    ("a dict of dataclasses converts",
     RS._jsonable({"x": _Op("B", _S.OPEN, _dt(2026, 9, 26))})["x"]["state"], "OPEN"),
]
for name, got, want in cases:
    ok = got == want
    bad += (not ok)
    print(f"  {'ok     ' if ok else 'WRONG  '} {name}" + ("" if ok else f"  got {got!r}"))

# it must be REAL json - no default=str to paper over it
try:
    json.dumps(RS._jsonable([_Op("A", _S.OPEN, _dt(2026, 9, 26))]))
    ok = True
except (TypeError, ValueError) as e:
    ok = False
bad += (not ok)
print(f"  {'ok     ' if ok else 'WRONG  '} the result is strictly serialisable "
      f"(no default=str)")

# recursion is bounded
deep = {}
cur = deep
for _ in range(40):
    cur["n"] = {}
    cur = cur["n"]
try:
    RS._jsonable(deep)
    ok = True
except RecursionError:
    ok = False
bad += (not ok)
print(f"  {'ok     ' if ok else 'WRONG  '} deep nesting does not blow the stack")

